def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    # The same colored motif occurs in two copies: retain the upper motif and
    # move the lower copy upward by the separation between matching motifs.
    # Identify each color's connected components and place all at top row 1.
    from collections import deque
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen:
                col=grid[r][c]; q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx]==col and (yy,xx) not in seen:
                            seen.add((yy,xx));q.append((yy,xx))
                comps.append((col,cells))
    for col,cells in comps:
        dy=1-min(r for r,c in cells)
        for r,c in cells: out[r+dy][c]=col
    return out
